float aspect = resolution.x / resolution.y;
vec2 p = vec2(uv.x * aspect, uv.y);
vec3 Y = vec3(0.299, 0.587, 0.114);
vec3 base = source(uv);
float kick = audio.beat;

// The film was painted at 12 frames a second, every frame anew: the strokes boil.
float boil = floor(time * (1.0 + 11.0 * param[2]));
float drift = time * 0.03;

// Smaller strokes as strength falls, so recognisability brings detail back before it fades.
float size = mix(0.022, 0.075, param[0]) * mix(0.35, 1.0, strength);
vec3 paint = base;

// Two layers: broad strokes that cover everything, then fine strokes only on detail.
for (int L = 0; L < 2; L++) {
  float cs = size * (L == 0 ? 1.0 : 0.45);
  vec2 g = p / cs;
  vec2 cell = floor(g);

  // The picture read once per cell corner: a stroke's colour and the form's direction.
  vec3 lat[16];
  for (int j = 0; j < 4; j++) {
    for (int i = 0; i < 4; i++) {
      vec2 q = (cell + vec2(float(i) - 1.0, float(j) - 1.0)) * cs;
      lat[j * 4 + i] = source(vec2(q.x / aspect, q.y));
    }
  }

  float bestP = -1.0;
  float bestBody = 9.0;
  vec3 bestC = vec3(0.0);
  vec2 bestST = vec2(0.0);
  vec2 bestDir = vec2(1.0, 0.0);
  float bestH = 0.0;
  float nearBody = 1e9;
  vec3 nearC = vec3(0.0);
  vec2 nearST = vec2(0.0);
  vec2 nearDir = vec2(1.0, 0.0);
  float nearH = 0.0;

  for (int b = -1; b <= 1; b++) {
    for (int a = -1; a <= 1; a++) {
      vec2 id = cell + vec2(float(a), float(b));
      int k = (b + 1) * 4 + (a + 1);
      vec3 c00 = lat[k];
      vec3 c10 = lat[k + 1];
      vec3 c01 = lat[k + 4];
      vec3 c11 = lat[k + 5];
      vec3 c = (c00 + c10 + c01 + c11) * 0.25;
      float gx = dot(c10 + c11 - c00 - c01, Y) * 0.5;
      float gy = dot(c01 + c11 - c00 - c10, Y) * 0.5;
      float edge = length(vec2(gx, gy));
      // Each stroke keeps its place; the boil only nudges it, as a repainted frame does.
      vec2 seed = id + vec2(float(L) * 31.7, 0.0);
      vec2 jolt = id + vec2(boil * 7.13, boil * 3.71);
      float h = hash(seed);
      if (L == 1 && edge < 0.05 + 0.06 * h) {
        continue;
      }
      vec2 centre = id + 0.3 + 0.4 * vec2(hash(seed + 1.3), hash(seed + 2.9));
      centre += 0.12 * (vec2(hash(jolt + 5.1), hash(jolt + 6.7)) - 0.5);

      // Where the picture is flat, paint follows a slow curl-noise current that gathers
      // into Van Gogh's swirls; on a contour the stroke follows the form instead.
      vec2 np = centre * cs * 2.2 + vec2(drift, -drift);
      float dx = valueNoise(np + vec2(0.05, 0.0)) - valueNoise(np - vec2(0.05, 0.0));
      float dy = valueNoise(np + vec2(0.0, 0.05)) - valueNoise(np - vec2(0.0, 0.05));
      vec2 flow = normalize(vec2(dy, -dx) + vec2(0.0001, 0.0));
      vec2 contour = normalize(vec2(-gy, gx) + vec2(0.0, 0.00001));
      contour *= sign(dot(contour, flow) + 0.0001);
      vec2 dir = normalize(mix(flow, contour, smoothstep(0.03, 0.1, edge)) + vec2(0.00001, 0.0));

      // Each hand lays a stroke a little askew; the kick shakes the whole canvas's brushwork.
      float wob = (hash(jolt) - 0.5) * (0.12 + 0.7 * kick);
      dir = vec2(dir.x * cos(wob) - dir.y * sin(wob), dir.x * sin(wob) + dir.y * cos(wob));

      vec2 d = g - centre;
      float hl = (0.55 + 0.3 * param[1]) * (1.0 + 0.08 * kick);
      float hw = 0.36 + 0.12 * hash(seed + 4.1);
      float s = dot(d, dir) / hl;
      // A stroke bends with the current, the way a wrist turns.
      float t = (dot(d, vec2(-dir.y, dir.x)) - (hash(seed + 8.3) - 0.5) * 0.5 * s * s * hl) / hw;
      float ragged = 0.2 * valueNoise(vec2(t * 3.0, h * 50.0));
      float body = max(abs(s) + ragged, abs(t) / (1.0 - 0.35 * s * s));
      if (body < 1.0 && h > bestP) {
        bestP = h;
        bestBody = body;
        bestC = c;
        bestST = vec2(s, t);
        bestDir = dir;
        bestH = h;
      }
      if (body < nearBody) {
        nearBody = body;
        nearC = c;
        nearST = vec2(s, t);
        nearDir = dir;
        nearH = h;
      }
    }
  }

  float cover = 1.0;
  if (bestP < 0.0) {
    if (L == 1) {
      continue;
    }
    bestC = nearC;
    bestST = nearST;
    bestDir = nearDir;
    bestH = nearH;
  } else if (L == 1) {
    cover = smoothstep(1.0, 0.8, bestBody);
  }

  // One loaded brush, one colour: saturated, each stroke a touch off its neighbours.
  vec3 c = bestC;
  float y = dot(c, Y);
  vec3 jitter = vec3(hash(vec2(bestH, 1.7)), hash(vec2(bestH, 2.3)), hash(vec2(bestH, 3.1))) - 0.5;
  c = pow(max(mix(vec3(y), c, 1.45) + jitter * 0.05, 0.0), vec3(1.15));
  // The painters mixed from a few tubes: every stroke leans toward the palette colour of its
  // own lightness, and one in three is laid almost in that colour, as an accent.
  float fi = clamp(dot(c, Y), 0.0, 1.0) * float(paletteSize - 1);
  int lo = int(floor(fi));
  int hi = min(lo + 1, paletteSize - 1);
  vec3 tube = mix(palette[lo], palette[hi], fi - float(lo));
  c = mix(c, tube, (hash(vec2(bestH, 4.9)) < 0.33 ? 0.6 : 0.2) * param[3]);

  // Bristle grooves along the stroke, and the ridge of thick paint lit from the top left.
  float s = bestST.x;
  float t = clamp(bestST.y, -1.0, 1.0);
  float br = valueNoise(vec2(t * 7.0 + bestH * 91.0, s * 0.8));
  float br2 = valueNoise(vec2((t + 0.12) * 7.0 + bestH * 91.0, s * 0.8));
  float height = (1.0 - t * t) * (0.55 + 0.45 * br);
  float slope = (br2 - br) * 2.0 - t * 0.3;
  float lit = slope * dot(vec2(-bestDir.y, bestDir.x), vec2(-0.6, 0.8));
  c *= 0.94 + 0.1 * br + 0.2 * lit;
  c += vec3(1.0, 0.95, 0.8) * max(lit, 0.0) * height * (0.08 + 0.4 * audio.high);
  paint = mix(paint, c, cover);
}

// Contours drawn in dark paint, as the painters outlined faces and hands.
vec2 r = vec2(size * 0.25 / aspect, size * 0.25);
float ex = dot(source(uv + vec2(r.x, 0.0)) - source(uv - vec2(r.x, 0.0)), Y);
float ey = dot(source(uv + vec2(0.0, r.y)) - source(uv - vec2(0.0, r.y)), Y);
float line = smoothstep(0.06, 0.2, length(vec2(ex, ey))) * 0.65;
line *= 0.55 + 0.45 * valueNoise(p / size * 3.0 + boil);
paint = mix(paint, palette[0], line * 0.8);

return mix(base, clamp(paint, 0.0, 1.0), smoothstep(0.0, 0.3, strength));
